const ee = require('@google/earthengine');
const privateKey = require('../auth_keys/test-project-473922-29f05d49bed7');

async function runAnalysis() {
  // Define global ocean region (exclude land)
  const ocean = ee.Geometry.Polygon(
    [[[-180, -60], [180, -60], [180, 60], [-180, 60], [-180, -60]]],
    null, false
  );

  // Time periods for comparison
  const period1Start = '2002-01-01';
  const period1End = '2003-12-31';
  const period2Start = '2021-01-01';
  const period2End = '2022-12-31';

  // Load MODIS Aqua Ocean Color data (chlorophyll-a as proxy for green hue)
  const col1 = ee.ImageCollection('NASA/OCEANDATA/MODIS-Aqua/L3SMI')
    .filterDate(period1Start, period1End)
    .filterBounds(ocean)
    .select('chlor_a');

  const col2 = ee.ImageCollection('NASA/OCEANDATA/MODIS-Aqua/L3SMI')
    .filterDate(period2Start, period2End)
    .filterBounds(ocean)
    .select('chlor_a');

  const size1 = col1.size().getInfo();
  const size2 = col2.size().getInfo();

  console.log(`2002-2003 Images: ${size1}`);
  console.log(`2021-2022 Images: ${size2}`);

  if (size1 === 0 || size2 === 0) {
    console.log("Empty collection for one or both periods.");
    console.log("<answer>C1</answer>");
    return;
  }

  // Create median composites for each period
  const img1 = col1.median();
  const img2 = col2.median();

  // Calculate statistics for both periods
  const stats1 = img1.reduceRegion({
    reducer: ee.Reducer.mean().combine({
      reducer2: ee.Reducer.count(),
      sharedInputs: true
    }),
    geometry: ocean,
    scale: 5000,
    maxPixels: 1e9,
    bestEffort: true
  }).getInfo();

  const stats2 = img2.reduceRegion({
    reducer: ee.Reducer.mean().combine({
      reducer2: ee.Reducer.count(),
      sharedInputs: true
    }),
    geometry: ocean,
    scale: 5000,
    maxPixels: 1e9,
    bestEffort: true
  }).getInfo();

  const mean1 = stats1.chlor_a_mean;
  const count1 = stats1.chlor_a_count;
  const mean2 = stats2.chlor_a_mean;
  const count2 = stats2.chlor_a_count;

  console.log(`2002-2003 Mean Chlorophyll: ${mean1} mg/m³, Pixels: ${count1}`);
  console.log(`2021-2022 Mean Chlorophyll: ${mean2} mg/m³, Pixels: ${count2}`);

  if (count1 === 0 || count2 === 0) {
    console.log("No valid pixels after processing.");
    console.log("<answer>C2</answer>");
    return;
  }

  if (mean1 === null || mean1 === undefined || mean2 === null || mean2 === undefined ||
      isNaN(mean1) || isNaN(mean2)) {
    console.log("Calculation failed - invalid results.");
    console.log("<answer>C3</answer>");
    return;
  }

  // Calculate percentage change
  const percentChange = ((mean2 - mean1) / mean1) * 100;
  console.log(`Chlorophyll change: ${percentChange.toFixed(2)}%`);

  // Green shift = increased chlorophyll-a (threshold: >2% increase)
  if (mean2 > mean1 && percentChange > 2) {
    console.log("Ocean surface shows greener hue in 2021-2022.");
    console.log("<answer>A</answer>");
  } else {
    console.log("No significant green shift detected.");
    console.log("<answer>B</answer>");
  }
}

async function initEE() {
  await new Promise((resolve, reject) => {
    ee.data.authenticateViaPrivateKey(privateKey, resolve, reject);
  });
  await new Promise((resolve, reject) => {
    ee.initialize(null, null, resolve, reject);
  });
  await runAnalysis();
}

initEE();
